import{_ as r,o,c as l,a5 as a,j as e}from"./chunks/framework.QWVCgkrI.js";const g=JSON.parse('{"title":"Gitのchanged-path Bloom filter：あるファイルの履歴を探すとき、なぜ木の比較を省けるのか","description":"","frontmatter":{"title":"Gitのchanged-path Bloom filter：あるファイルの履歴を探すとき、なぜ木の比較を省けるのか","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"tools","summary":"第1親と対象パスを比べる前に、変更がないと分かる場合を図で追う。偽陽性、マージ、名前変更の追跡との関係も整理する。","aliases":["changed-path Bloom filter","changed paths Bloom filter","変更パスのBloom filter","Gitのパス履歴"],"verification":"Git公式資料とソースを参照し、Git for Windows 2.39.2で単一パスの履歴とTrace2の集計を検証（2026-11-21）"}},"headers":[],"relativePath":"tools/git-changed-path-bloom-filter.md","filePath":"tools/git-changed-path-bloom-filter.md"}'),i={name:"tools/git-changed-path-bloom-filter.md"};function c(s,t,n,p,d,m){return o(),l("div",null,[...t[0]||(t[0]=[a('<h1 id="gitのchanged-path-bloom-filter-あるファイルの履歴を探すとき、なぜ木の比較を省けるのか" tabindex="-1">Gitのchanged-path Bloom filter：あるファイルの履歴を探すとき、なぜ木の比較を省けるのか <a class="header-anchor" href="#gitのchanged-path-bloom-filter-あるファイルの履歴を探すとき、なぜ木の比較を省けるのか" aria-label="Permalink to &quot;Gitのchanged-path Bloom filter：あるファイルの履歴を探すとき、なぜ木の比較を省けるのか&quot;">​</a></h1><p><code>git log -- player.cpp</code> で、プレイヤーの処理をいつ変更したかを探します。途中には、音やUIだけを変えたコミットもあります。<code>player.cpp</code> がそのコミットで変わったかを調べるには、保存されたファイルの木（tree）を親の木と比べます。Gitの <strong>changed-path Bloom filter</strong>（変更パスのブルームフィルター）は、比較する前に、対象パスが第1親から変わっていないと分かる場合を見つけるための索引です。<a href="https://git-scm.com/docs/gitformat-commit-graph" target="_blank" rel="noreferrer">Gitのcommit-graphファイル形式</a> · <a href="https://git-scm.com/docs/git-commit-graph" target="_blank" rel="noreferrer">git commit-graph</a></p><h2 id="この記事で分かること" tabindex="-1">この記事で分かること <a class="header-anchor" href="#この記事で分かること" aria-label="Permalink to &quot;この記事で分かること&quot;">​</a></h2><p><code>git log -- player.cpp</code> で木の比較を省ける条件と、実際に木を比べる必要がある条件を区別できます。マージやリネームの追跡では、第1親に対する固定パスの判定から何が分かるかを説明できます。</p><h2 id="コミットごとに、第1親から変わったパスを記録する" tabindex="-1">コミットごとに、第1親から変わったパスを記録する <a class="header-anchor" href="#コミットごとに、第1親から変わったパスを記録する" aria-label="Permalink to &quot;コミットごとに、第1親から変わったパスを記録する&quot;">​</a></h2><p>commitオブジェクトは、その時点のルートtreeと親のIDを指します。treeにはファイルやディレクトリの名前、モード、参照先が入ります。たとえば親と子で <code>player.cpp</code> の項目が同じなら、そのパスに変更はありません。索引を作るとき、Gitは第1親との比較で変わったパスを調べ、その情報をコミットごとのフィルターにまとめます。フィルターはcommit-graphに追加できる補助データで、<code>git commit-graph write --reachable --changed-paths</code> で生成できます。<a href="/study/tools/git-objects.html">Gitの保存モデル</a> · <a href="https://git-scm.com/docs/gitformat-commit-graph" target="_blank" rel="noreferrer">Gitのcommit-graphファイル形式</a> · <a href="https://git-scm.com/docs/git-commit-graph" target="_blank" rel="noreferrer">git commit-graph</a></p><p>固定したパスを検索するとき、使えるフィルターが「第1親から変更なし」と返せば、その比較を省けます。「変わった可能性あり」なら、実際にtreeを比べて確かめます。フィルターがないコミットもtreeを比べます。比較を省ける場合でも、履歴探索は必要な親をたどり続けます。<a href="https://github.com/git/git/blob/v2.52.0/revision.c#L727-L821" target="_blank" rel="noreferrer">Git 2.52.0の比較処理</a></p><h2 id="立っているビットは、どのファイルが立てたかを覚えていない" tabindex="-1">立っているビットは、どのファイルが立てたかを覚えていない <a class="header-anchor" href="#立っているビットは、どのファイルが立てたかを覚えていない" aria-label="Permalink to &quot;立っているビットは、どのファイルが立てたかを覚えていない&quot;">​</a></h2><p>Bloom filterは、集合に対象があるかをビット列で調べる仕組みです。以下の概念図では、パス名をハッシュで0〜7のうち2つの位置に写します。変更した <code>weapon.cpp</code> は位置1と4を、<code>hud.cpp</code> は3と6を1にします。Gitが実際に使うハッシュ値やビット数は、この図とは異なります。<a href="https://git-scm.com/docs/gitformat-commit-graph#_chunk_data" target="_blank" rel="noreferrer">Gitのcommit-graphファイル形式</a></p>',9),e("figure",{style:{margin:"1rem 0"}},[e("div",{role:"img","aria-label":"8ビットの概念図。位置は0から7。weapon.cpp が1と4、hud.cpp が3と6を立てる。記録は0、1、0、1、1、0、1、0。",style:{"max-width":"32rem","font-size":".88em","font-variant-numeric":"tabular-nums"}},[e("div",{style:{display:"grid","grid-template-columns":"6.5rem repeat(8, minmax(0, 1fr))",gap:".22rem .12rem","align-items":"center","text-align":"center"}},[e("span",{style:{"text-align":"left"}},"位置"),e("span",null,"0"),e("span",null,"1"),e("span",null,"2"),e("span",null,"3"),e("span",null,"4"),e("span",null,"5"),e("span",null,"6"),e("span",null,"7"),e("div",{"data-bloom-row":"weapon",style:{display:"contents"}},[e("strong",{style:{"text-align":"left"}},"weapon.cpp"),e("span",null,"·"),e("span",null,"1"),e("span",null,"·"),e("span",null,"·"),e("span",null,"1"),e("span",null,"·"),e("span",null,"·"),e("span",null,"·")]),e("div",{"data-bloom-row":"hud",style:{display:"contents"}},[e("strong",{style:{"text-align":"left"}},"hud.cpp"),e("span",null,"·"),e("span",null,"·"),e("span",null,"·"),e("span",null,"1"),e("span",null,"·"),e("span",null,"·"),e("span",null,"1"),e("span",null,"·")]),e("div",{"data-bloom-row":"stored",style:{display:"contents"}},[e("strong",{style:{"text-align":"left"}},"保存する値"),e("span",null,"0"),e("span",{style:{background:"var(--vp-c-brand-soft)","border-radius":"3px"}},"1"),e("span",null,"0"),e("span",{style:{background:"var(--vp-c-brand-soft)","border-radius":"3px"}},"1"),e("span",{style:{background:"var(--vp-c-brand-soft)","border-radius":"3px"}},"1"),e("span",null,"0"),e("span",{style:{background:"var(--vp-c-brand-soft)","border-radius":"3px"}},"1"),e("span",null,"0")])])]),e("figcaption",{style:{"font-size":".875rem","margin-top":".55rem"}},"2つのパスが立てたビットを、コミットの1本のビット列にまとめる。「·」の位置はそのパスでは立てない。")],-1),a(`<ul><li><code>camera.cpp</code> が位置1と5を参照する場合、5は0です。変更していたなら5も1になるので、このパスは第1親から変わっていないと分かります。</li><li><code>player.cpp</code> が位置1と6を参照する場合、どちらも1です。実際には別々のファイルが立てたビットですが、フィルターだけでは区別できません。変更していないのに候補に残るのが <strong>偽陽性</strong> です。treeを比べて、第1親から変わったかを確かめます。</li></ul><p>図の例では、未変更のパスなのに比較が発生することがあります。省ける比較の数は、対象パスが変わる頻度、使えるフィルターの範囲、偽陽性の多さなどで変わります。処理時間には、フィルターの読み取りと照会の費用も含まれます。<a href="https://github.com/git/git/blob/v2.52.0/revision.c#L727-L821" target="_blank" rel="noreferrer">Git 2.52.0の比較処理</a></p><h2 id="世代番号・マージ・リネームと、答えられる問いを分ける" tabindex="-1">世代番号・マージ・リネームと、答えられる問いを分ける <a class="header-anchor" href="#世代番号・マージ・リネームと、答えられる問いを分ける" aria-label="Permalink to &quot;世代番号・マージ・リネームと、答えられる問いを分ける&quot;">​</a></h2><p><a href="/study/tools/git-commit-graph.html">世代番号</a>を使う祖先判定が省くのは、候補へ到達できない枝をさらにたどる仕事です。変更パスのフィルターが省くのは、あるコミットと第1親の間で、対象パスのtreeを比較する仕事です。両方ともcommit-graphに保存でき、判断する情報は別々です。<a href="https://git-scm.com/docs/commit-graph" target="_blank" rel="noreferrer">Gitのcommit-graph設計文書</a> · <a href="https://git-scm.com/docs/gitformat-commit-graph" target="_blank" rel="noreferrer">Gitのcommit-graphファイル形式</a></p><p><strong>マージの場合</strong>、マージ結果の <code>player.cpp</code> が第1親と同じでも、第2親とは違う場合があります。フィルターを参照できるのは第1親との比較です。どの親をたどり、どのコミットを表示するかは、<code>git log</code> の履歴を絞る規則やオプションにも従います。<a href="https://github.com/git/git/blob/v2.52.0/revision.c#L770-L821" target="_blank" rel="noreferrer">Git 2.52.0の比較処理</a> · <a href="https://git-scm.com/docs/git-log#_history_simplification" target="_blank" rel="noreferrer">git logの履歴の簡略化</a></p><p><strong>リネームの場合</strong>、<code>player.cpp</code> が以前は <code>hero.cpp</code> だったとします。固定パスのフィルターに問い合わせても、新旧のパス名の対応までは分かりません。1ファイルを対象にする <code>git log --follow -- player.cpp</code> は、名前の変更を検出しながら旧名でも履歴を探します。途中で探すパスが変わるので、固定パスの例をそのまま当てはめることはできません。<a href="https://git-scm.com/docs/git-log#Documentation/git-log.txt---follow" target="_blank" rel="noreferrer">git logの <code>--follow</code></a> · <a href="https://github.com/git/git/blob/v2.52.0/revision.c#L2959-L2982" target="_blank" rel="noreferrer">Git 2.52.0の履歴探索設定</a></p><h2 id="要点" tabindex="-1">要点 <a class="header-anchor" href="#要点" aria-label="Permalink to &quot;要点&quot;">​</a></h2><ul><li>変更パスのBloom filterは、第1親との差を要約する、commit-graphの任意の索引です。</li><li>参照するビットに0があれば、そのパスの比較を省けます。全部1ならtreeを比べて変更の有無を確かめます。</li><li>世代番号は祖先へ届く可能性を調べるために使います。マージの第2親以降とリネーム前後の対応には、同じパス判定をそのまま使えません。</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><details class="details custom-block"><summary><code>player.cpp</code> の位置1と6が両方1なら、このコミットで変更したことになる？</summary><p>両方1でも、別のパスがその位置を立てた可能性があります。第1親とのtree比較で確かめます。</p></details><details class="details custom-block"><summary>マージの第1親から変更がないと分かったら、第2親との比較結果も分かる？</summary><p>フィルターが表すのは第1親との差です。第2親の <code>player.cpp</code> が同じかは、その親との比較が必要です。</p></details><h2 id="検証範囲" tabindex="-1">検証範囲 <a class="header-anchor" href="#検証範囲" aria-label="Permalink to &quot;検証範囲&quot;">​</a></h2><p>2026年11月21日にGit公式資料と実装を確認しました。Git for Windows <code>2.39.2.windows.1</code> の独立したSHA-1リポジトリに、<code>player.cpp</code> の追加と編集、他のファイルだけを変えるコミットを含む直線の履歴を5件作りました。<code>git log --format=%s -- player.cpp</code> は、フィルター生成前と、生成後にこの版の <code>commitGraph.readChangedPaths</code> を切り替えた場合のいずれも次の2件でした。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>D edit player</span></span>
<span class="line"><span>B add player</span></span></code></pre></div><p><code>git commit-graph verify</code> は成功しました。フィルターの読み取りを有効にすると、GitのTrace2診断には <code>maybe: 2</code>、<code>definitely_not: 2</code>、<code>false_positive: 0</code> が記録されました。</p><p>次に、<code>player.cpp</code> の照会に必要なビットがすべて立つよう意図的に選んだ <code>side-110.txt</code> だけを追加し、索引を作り直しました。再検証でも履歴の出力は同じ2件で、Trace2の <code>maybe</code> は3、<code>false_positive</code> は1になりました。フィルターが候補に残したコミットを、実際のtree比較で除外できた例です。この件数は意図的に作った履歴での観察です。処理時間、通常の履歴における偽陽性の割合、マージや <code>--follow</code> でのフィルター利用は測定していません。<a href="https://github.com/git/git/blob/v2.39.2/revision.c#L726-L781" target="_blank" rel="noreferrer">Git 2.39.2のTrace2集計</a></p><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/study/tools/git-commit-graph.html">Gitのcommit-graph</a> — 世代番号で親をたどる範囲を絞る例を読む。</li><li><a href="/study/tools/git-objects.html">Gitの保存モデル</a> — commit・tree・blobがどこに情報を持つかを確認する。</li></ul><h2 id="参考資料" tabindex="-1">参考資料 <a class="header-anchor" href="#参考資料" aria-label="Permalink to &quot;参考資料&quot;">​</a></h2><ul><li><a href="https://git-scm.com/docs/gitformat-commit-graph" target="_blank" rel="noreferrer">Git — gitformat-commit-graph</a> — 第1親からの変更パスとビット列の保存形式。</li><li><a href="https://git-scm.com/docs/git-commit-graph" target="_blank" rel="noreferrer">Git — git commit-graph</a> — 変更パスのフィルターの生成と読み取り設定。</li><li><a href="https://git-scm.com/docs/git-log" target="_blank" rel="noreferrer">Git — git log</a> — パスを指定した履歴、履歴の簡略化、<code>--follow</code>。</li><li><a href="https://github.com/git/git/blob/v2.52.0/revision.c#L727-L821" target="_blank" rel="noreferrer">Git 2.52.0 — revision.c</a> — 第1親のフィルターを参照し、変更がなければtree比較を省く処理。</li></ul>`,20)])])}const f=r(i,[["render",c]]);export{g as __pageData,f as default};
